CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, lifecycle TEXT NOT NULL DEFAULT 'planned', repository TEXT, base_url TEXT, environment TEXT NOT NULL DEFAULT 'production', owner TEXT NOT NULL DEFAULT 'DomisLink', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_dependencies (service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, dependency_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, PRIMARY KEY(service_id,dependency_id), CHECK(service_id <> dependency_id));
CREATE TABLE IF NOT EXISTS integration_approvals (id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id), client_id TEXT NOT NULL, requested_scopes TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('requested','approved','rejected','revoked')), requested_by TEXT NOT NULL, decided_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_at TEXT);
CREATE TABLE IF NOT EXISTS health_observations (id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id), status TEXT NOT NULL CHECK(status IN ('healthy','degraded','down','unknown')), checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, detail TEXT);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_sub TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_approvals_service ON integration_approvals(service_id,created_at);
CREATE INDEX IF NOT EXISTS idx_health_service ON health_observations(service_id,checked_at);
